// BALL46 Event Flow SIGNAL annotation: premium elevated surface, no rectangle stroke.
// Scoped to the real SVG generated by expanded-match-343.js. No data, JS, or graph-line changes.
export const MARKER='b46-eventflow-signal-soft-elevation-20261020';
export const STYLE=String.raw`<style id="b46-eventflow-signal-soft-elevation-20261020">
/* The card is an SVG rect, not a CSS HTML border. Keep its connecting line and timeline marker. */
svg g.b46-eventflow-signal-entry.b46-eventflow-signal-annotation > rect{
  stroke:none!important;
  stroke-width:0!important;
  fill:#12392f!important;
  fill-opacity:.95!important;
  filter:drop-shadow(0 5px 7px rgba(0,0,0,.35)) drop-shadow(0 -1px 2px rgba(68,228,164,.17))!important;
}
</style>`;
export function inject(html){
  if(typeof html!=='string'||!html.includes('</head>'))throw Error('SIGNAL_HTML_INVALID');
  for(const required of ['b46-mobile-ultrasoft-flow-v3-20261020','b46-pc-hide-result-ticker-20261020','b46-pc-ticker-gap-fix-20261020']){
    if(!html.includes(required))throw Error('LATEST_PRODUCTION_FEATURE_MISSING '+required);
  }
  if(html.includes(MARKER))throw Error('SIGNAL_CARD_ELEVATION_ALREADY_PRESENT');
  return html.replace('</head>',STYLE+'</head>');
}
